    var settings = $.extend({
        selector: 'th:visible',
        asc: 'asc',
        desc: 'desc'
    }, o);

    var asc = this.data(settings.asc);
    var desc = this.data(settings.desc);

    if (asc) {
        this.data(settings.asc, !asc);
    } else {
        this.data(settings.asc, true);
    }

    var desc = this.data(settings.desc);

    if (desc) {
        this.data(settings.desc, !desc);
    } else {
        this.data(settings.desc, true);
    }

    return this.each(function() {
        var this_ = this;
        var table = $(this);

        $(settings.selector, table).click(function() {
            var column = $(this).index();
            var key = this_.data(settings.asc);

            // Get data from table rows
            var row = $('tr', this).not(':hidden').not(':gt(0)');

            // Sort by specified key
            row.sort(function(a, b) {
                a = a.getElementsByTagName('td')[column].innerText.toLowerCase();
                b = b.getElementsByTagName('td')[column].innerText.toLowerCase();
                if ((key && (a < b)) || (!key && (a > b)))
                    return -1;
                if ((key && (a > b)) || (!key && (a < b)))
                    return 1;
                return 0;
            });

            // Append sorted rows to table
            table.find('tr:not(:hidden):not(:gt(0))').remove();
            table.append(row);
        });
    });

